export function answerMatches(actual,expected){const norm=x=>String(x??'').trim().toLowerCase().replace(/[.,!?]/g,'').replace(/\s+/g,' ');const aliases={'eight':['8'],'three':['3'],'twenty-four':['24','twenty four'],'english book':['book','an english book']};return [expected,...(aliases[expected]||[])].some(x=>norm(x)===norm(actual));}
